     "lead": "Усреднитель — регулирующий резервуар, который заполняется в часы максимального притока и опорожняется в часы минимального; он сглаживает колебания расхода и концентраций перед следующими сооружениями [^1,2]. Благодаря ему можно уменьшить отстойники, илоразделение и доочистку и сделать работу биореакторов стабильнее [^2].",
