     "lead": "Аэротенк с нитри-денитрификацией удаляет из воды не только органику, но и азот: в аэробной зоне бактерии окисляют аммоний до нитратов, а в аноксидной (без кислорода, но с нитратами) другие бактерии восстанавливают нитраты до газообразного азота, используя органику стоков [^1,2]. Самая распространённая схема — модифицированный процесс Лудзака—Эттингера (МЛЭ) с предвключённой денитрификацией [^1].",
