     "lead": "Обратный осмос — продавливание воды под давлением выше осмотического через полупроницаемую мембрану, которая пропускает молекулы воды и задерживает почти все растворённые соли и органику [^1]. Получается обессоленный пермеат и концентрат, в котором собраны задержанные вещества [^1].",
