       "Свод правил задаёт расчётную частицу: до средних станций включительно — песок 0,2 мм и крупнее (гидравлическая крупность 18,7 мм/с), на станциях от больших, а также на средних без первичного осветления — 0,15 мм (13,2 мм/с) [^1]. Чем мельче расчётная частица, тем больше объём песколовки, но тем меньше песка дойдёт до отстойников и аэротенков [^1,2].\n\nГидравлическая крупность $u_0$ — это скорость оседания частицы в спокойной воде; для мелких частиц её описывает закон Стокса [^4]:\n\n$$ u_0 = \\frac{g\\,(\\rho_ч - \\rho_в)\\,d^2}{18\\,\\mu} $$\n\n- $\\rho_ч$, $\\rho_в$ — плотность частицы и воды, кг/м³\n- $d$ — диаметр частицы, м\n- $\\mu$ — динамическая вязкость воды, Па·с\n\nЗакон Стокса для песка (2650 кг/м³) при 20 °C справедлив только для частиц до 0,13 мм; для частиц 0,15–0,2 мм используют формулу переходного режима, поэтому свод правил задаёт гидравлическую крупность готовыми числами [^1,5]."
