     "lead": "Растворённый кислород — кислород, растворённый в воде; от него зависит жизнь аэробных бактерий в аэротенке и рыб в водоёме [^1,2]. На очистных его концентрацию поддерживают аэрацией, а в водоёме сброс сточных вод не должен снижать её ниже нормы [^2,3].",
