     "lead": "pH — отрицательный десятичный логарифм активности ионов водорода; он показывает, кислая (pH < 7), нейтральная или щелочная (pH > 7) реакция воды [^1]. От pH зависят скорость биологических процессов, формы аммонийного азота и хлора, растворимость металлов [^1,2].",
