     "lead": "Щёлочность — способность воды нейтрализовать кислоту; в сточных водах её создают в основном гидрокарбонаты [^1,2]. Щёлочность — буфер, который не даёт pH упасть при нитрификации и вводе коагулянтов [^2].",
