     "lead": "Солесодержание (общая минерализация) — суммарная концентрация растворённых неорганических солей: хлоридов, сульфатов, гидрокарбонатов натрия, кальция, магния и др. [^1,2]. Его оценивают по сухому остатку — массе вещества, оставшегося после выпаривания отфильтрованной пробы и высушивания [^3].",
